-- ENAT-iTEST | Esquema inicial da avaliação nacional
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,state_code text not null check(state_code in('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO')),role text not null default 'participant' check(role in('participant','admin')),created_at timestamptz not null default now());
create table if not exists public.question_bank(id text primary key,discipline_code text not null check(discipline_code in('DD','LT','CRT','INF','NGCC','SIN','PS','CID','MEI','MEC','RI','PST','PRA','ENGT','DID','NAT','FAP')),discipline_name text not null,prompt text not null,options jsonb not null check(jsonb_typeof(options)='array' and jsonb_array_length(options)>=2),answer_index integer not null check(answer_index>=0),explanation text not null default '',hsi_dimension text check(hsi_dimension is null or hsi_dimension in('decision','organization','time','humanization','psychocomportamental')),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint question_answer_within_options check(answer_index<jsonb_array_length(options)));
create table if not exists public.assessment_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,state_code text not null check(state_code in('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO')),total_questions integer not null default 30 check(total_questions=30),correct_count integer,score numeric(4,2) check(score is null or(score>=0 and score<=10)),status text not null default 'in_progress' check(status in('in_progress','completed','cancelled')),created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.attempt_questions(attempt_id uuid not null references public.assessment_attempts(id) on delete cascade,question_id text not null references public.question_bank(id),position integer not null check(position between 1 and 30),primary key(attempt_id,question_id),unique(attempt_id,position));
create table if not exists public.attempt_answers(attempt_id uuid not null,question_id text not null,selected_index integer not null check(selected_index>=0),correct_index integer not null check(correct_index>=0),is_correct boolean not null,prompt_snapshot text not null,options_snapshot jsonb not null,explanation_snapshot text not null default '',created_at timestamptz not null default now(),primary key(attempt_id,question_id),foreign key(attempt_id,question_id) references public.attempt_questions(attempt_id,question_id) on delete cascade);
create table if not exists public.state_metrics(state_code text primary key check(state_code in('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO')),participants_count bigint not null default 0,attempts_count bigint not null default 0,score_total numeric(14,2) not null default 0,approved_count bigint not null default 0,updated_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.question_bank enable row level security;alter table public.assessment_attempts enable row level security;alter table public.attempt_questions enable row level security;alter table public.attempt_answers enable row level security;alter table public.state_metrics enable row level security;
drop policy if exists "participants read own profile" on public.profiles;create policy "participants read own profile" on public.profiles for select to authenticated using(id=(select auth.uid()));
drop policy if exists "participants update own profile" on public.profiles;create policy "participants update own profile" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
drop policy if exists "participants read own attempts" on public.assessment_attempts;create policy "participants read own attempts" on public.assessment_attempts for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "authenticated read aggregate metrics" on public.state_metrics;create policy "authenticated read aggregate metrics" on public.state_metrics for select to authenticated using(true);
grant usage on schema public to authenticated,service_role;grant select on public.profiles,public.assessment_attempts,public.state_metrics to authenticated;grant update(full_name,state_code) on public.profiles to authenticated;grant all on all tables in schema public to service_role;
create or replace function private.handle_new_enat_profile() returns trigger language plpgsql security definer set search_path='' as $$
declare v_state text;v_name text;begin v_state:=upper(coalesce(new.raw_user_meta_data->>'state_code',''));v_name:=nullif(trim(coalesce(new.raw_user_meta_data->>'full_name','')),'');
if v_state not in('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO') then raise exception 'Selecione uma unidade federativa válida.';end if;
insert into public.profiles(id,full_name,state_code) values(new.id,coalesce(v_name,'Participante'),v_state);
insert into public.state_metrics(state_code,participants_count) values(v_state,1) on conflict(state_code) do update set participants_count=public.state_metrics.participants_count+1,updated_at=now();return new;end;$$;
revoke all on function private.handle_new_enat_profile() from public,anon,authenticated;
drop trigger if exists on_auth_user_created_enat_profile on auth.users;create trigger on_auth_user_created_enat_profile after insert on auth.users for each row execute function private.handle_new_enat_profile();
create or replace function private.sync_profile_state_metrics() returns trigger language plpgsql security definer set search_path='' as $$
begin if old.state_code is distinct from new.state_code then update public.state_metrics set participants_count=greatest(participants_count-1,0),updated_at=now() where state_code=old.state_code;
insert into public.state_metrics(state_code,participants_count) values(new.state_code,1) on conflict(state_code) do update set participants_count=public.state_metrics.participants_count+1,updated_at=now();end if;return new;end;$$;
revoke all on function private.sync_profile_state_metrics() from public,anon,authenticated;
drop trigger if exists on_profile_state_changed on public.profiles;create trigger on_profile_state_changed after update of state_code on public.profiles for each row execute function private.sync_profile_state_metrics();
create or replace function private.aggregate_completed_assessment() returns trigger language plpgsql security definer set search_path='' as $$
begin if old.status='in_progress' and new.status='completed' then update public.state_metrics set attempts_count=attempts_count+1,score_total=score_total+coalesce(new.score,0),approved_count=approved_count+case when coalesce(new.score,0)>=7 then 1 else 0 end,updated_at=now() where state_code=new.state_code;end if;return new;end;$$;
revoke all on function private.aggregate_completed_assessment() from public,anon,authenticated;
drop trigger if exists on_assessment_completed_aggregate on public.assessment_attempts;create trigger on_assessment_completed_aggregate after update of status on public.assessment_attempts for each row execute function private.aggregate_completed_assessment();